-- The sheet's floor: a claim's live due is at least it. Settled, stated and closed figures keep
-- what they were fixed at.
ALTER TABLE sheet ADD COLUMN floor DECIMAL(14, 2) DEFAULT 1.00 NOT NULL;

-- The sheet's terms: the number of days after its date a claim is due by. An OPEN claim whose
-- due-by is before the sheet's today is overdue.
ALTER TABLE sheet ADD COLUMN terms INT DEFAULT 14 NOT NULL;

-- The sheet's late percent: an overdue claim's due gains this percent of its figure for every
-- full 30 days it is overdue. Never bound by a statement; frozen in when the claim is settled.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(5, 2) DEFAULT 0.00 NOT NULL;

-- The role a user name has on a sheet: clerk or steward. A name with no row is a clerk.
CREATE TABLE sheet_role (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(64)  NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200) NOT NULL,
    role      VARCHAR(16)  NOT NULL CHECK (role IN ('clerk', 'steward'))
);
CREATE UNIQUE INDEX sheet_role_user ON sheet_role (sheet_id, user_name);
-- The sheet's clerk limit: a clerk can settle a claim only when its due is at or below it (a claim
-- whose due is n/a is within any limit). Null means no limit.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(14, 2);

-- Terms per grade: a grade's own terms in days; null means the grade uses the sheet's terms.
ALTER TABLE sheet ADD COLUMN terms_a INT;
ALTER TABLE sheet ADD COLUMN terms_b INT;
ALTER TABLE sheet ADD COLUMN terms_c INT;
-- A claim's due-by is fixed when it is added, from the terms of its person's grade in force on its
-- date; later changes to the terms or the claim's date do not move it. Existing claims take their
-- date plus the sheet's terms.
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim c SET due_by = DATEADD(DAY, (SELECT s.terms FROM sheet s WHERE s.id = c.sheet_id), c.claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;

-- The sheet's cap: a person's due-total is at most it, the excess shown apart. Null means no cap.
ALTER TABLE sheet ADD COLUMN cap DECIMAL(14, 2);

-- The sheet's policy date: a claim dated before it rounds its live figures half up, one dated on or
-- after it half to even (a correction by the date of the claim it corrects). Null means the sheet's
-- today. Settled and stated figures keep what they were fixed at.
ALTER TABLE sheet ADD COLUMN policy_date DATE;

-- Period numbering: from the sheet's period-numbering-from date (null: off), a claim opened while the
-- sheet's today is on or after it is numbered within the period its date falls in, <period name>-<n>,
-- counting from 1 in each period (the period keeps the last it gave out), or X-<n> in the sheet's own
-- sequence for a claim in no period. Claims numbered before keep their sheet-wide numbers, and the
-- sheet-wide sequence carries on when the setting is cleared. A claim's number, and the number a
-- correction names, are now text.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
ALTER TABLE sheet ADD COLUMN last_unperiod_claim_number INT DEFAULT 0 NOT NULL;
ALTER TABLE period ADD COLUMN last_claim_number INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ALTER COLUMN claim_number VARCHAR(220);
ALTER TABLE claim ALTER COLUMN corrects VARCHAR(220);

-- A sheet: the unit everything else in the app is kept per. Created the first time its id is loaded.
CREATE TABLE sheet (
    id         VARCHAR(64) PRIMARY KEY,
    created_at TIMESTAMP   NOT NULL
);

-- The sheet's "today": the date every date-dependent decision and default date on the sheet uses,
-- never the real clock. A new sheet starts on the real date; it is changed on the screen.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CAST(created_at AS DATE);
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;

