package net.officefloor.hq.app.sheet;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Instant;
import net.officefloor.hq.app.Audit;
import java.time.LocalDate;
import net.officefloor.hq.app.rollup.Rollups;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Loads sheets by id; an id never loaded before starts a new, empty sheet. */
@Service
public class SheetService {

    private final SheetRepository sheets;
    private final Rollups rollups;
    private final Audit audit;

    public SheetService(SheetRepository sheets, Rollups rollups, Audit audit) {
        this.sheets = sheets;
        this.rollups = rollups;
        this.audit = audit;
    }

    /** Load a sheet; a new sheet's today starts as the real date. */
    @Transactional
    public synchronized Sheet load(String id) {
        return sheets.findById(id).orElseGet(() -> sheets.save(new Sheet(id, Instant.now(), LocalDate.now())));
    }

    /**
     * The sheet's today. Every date-dependent decision and every default date on a sheet uses
     * this, never the real clock.
     */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return load(id).getToday();
    }

    /**
     * Take the sheet's lock, holding it until the caller's transaction ends, so changes that check
     * the sheet's other rows before writing are made one at a time.
     */
    @Transactional
    public Sheet lock(String id) {
        load(id);
        return sheets.findLockedById(id).orElseThrow();
    }

    /** Change the sheet's today, auditing the figures that moves. */
    @Transactional
    public synchronized Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = load(id);
        Rollups.Rollup before = rollups.take(id);
        sheet.setToday(today);
        Sheet saved = sheets.saveAndFlush(sheet);
        rollups.audit(id, user, before);
        return saved;
    }

    /** The sheet's clerk limit; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal clerkLimit(String id) {
        return load(id).getClerkLimit();
    }

    /** Change the sheet's clerk limit (null: no limit), auditing the change. */
    @Transactional
    public Sheet setClerkLimit(String id, String user, BigDecimal limit) {
        Sheet sheet = lock(id);
        sheet.setClerkLimit(limit == null ? null : limit.setScale(2, RoundingMode.UNNECESSARY));
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=clerk-limit value="
                + (saved.getClerkLimit() == null ? "" : saved.getClerkLimit().toPlainString()));
        return saved;
    }

    /** Change the sheet's cap (null: no cap), auditing the change and the figures it moves. */
    @Transactional
    public Sheet setCap(String id, String user, BigDecimal cap) {
        Sheet sheet = lock(id);
        Rollups.Rollup before = rollups.take(id);
        sheet.setCap(cap == null ? null : cap.setScale(2, RoundingMode.UNNECESSARY));
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=cap value="
                + (saved.getCap() == null ? "" : saved.getCap().toPlainString()));
        rollups.audit(id, user, before);
        return saved;
    }

    /** Change the sheet's floor, auditing the change and the figures it moves. */
    @Transactional
    public Sheet setFloor(String id, String user, BigDecimal floor) {
        Sheet sheet = lock(id);
        Rollups.Rollup before = rollups.take(id);
        sheet.setFloor(floor.setScale(2, RoundingMode.UNNECESSARY));
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=floor value="
                + saved.getFloor().toPlainString());
        rollups.audit(id, user, before);
        return saved;
    }

    /** Change the sheet's terms, in days, auditing the change; claims keep their due-by. */
    @Transactional
    public Sheet setTerms(String id, String user, int terms) {
        Sheet sheet = lock(id);
        Rollups.Rollup before = rollups.take(id);
        sheet.setTerms(terms);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=terms value=" + saved.getTerms());
        rollups.audit(id, user, before);
        return saved;
    }

    /** Change a grade's own terms, in days (null: the sheet's terms), auditing the change. Claims keep their due-by. */
    @Transactional
    public Sheet setGradeTerms(String id, String user, String grade, Integer terms) {
        Sheet sheet = lock(id);
        Rollups.Rollup before = rollups.take(id);
        sheet.setGradeTerms(grade, terms);
        Sheet saved = sheets.saveAndFlush(sheet);
        Integer value = saved.getGradeTerms(grade);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=terms-" + grade + " value="
                + (value == null ? "" : value.toString()));
        rollups.audit(id, user, before);
        return saved;
    }

    /** Change the sheet's late percent, auditing the change and the figures it moves. */
    @Transactional
    public Sheet setLatePct(String id, String user, BigDecimal latePct) {
        Sheet sheet = lock(id);
        Rollups.Rollup before = rollups.take(id);
        sheet.setLatePct(latePct.setScale(2, RoundingMode.UNNECESSARY));
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=late-pct value="
                + saved.getLatePct().toPlainString());
        rollups.audit(id, user, before);
        return saved;
    }

    /** Change the sheet's policy date (null: the sheet's today), auditing the change and the figures it moves. */
    @Transactional
    public Sheet setPolicyDate(String id, String user, LocalDate policyDate) {
        Sheet sheet = lock(id);
        Rollups.Rollup before = rollups.take(id);
        sheet.setPolicyDate(policyDate);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=policy-date value="
                + (saved.getPolicyDate() == null ? "" : saved.getPolicyDate().toString()));
        rollups.audit(id, user, before);
        return saved;
    }

    /** Change the sheet's period-numbering-from date (null: off), auditing the change. */
    @Transactional
    public Sheet setPeriodNumberingFrom(String id, String user, LocalDate from) {
        Sheet sheet = lock(id);
        sheet.setPeriodNumberingFrom(from);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=period-numbering-from value="
                + (saved.getPeriodNumberingFrom() == null ? "" : saved.getPeriodNumberingFrom().toString()));
        return saved;
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one audit record once the current transaction commits, so a change that is refused or
     * rolled back writes nothing. Records outside a transaction are appended at once.
     */
    public void recordOnCommit(String entry) {
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            record(entry);
            return;
        }
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                record(entry);
            }
        });
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

