package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Component;

/** What is due on a claim, read from the rates its person's grade has. */
@Component
public class Dues {

    private final RateRepository rates;
    private final SheetRepository sheets;
    private final ClaimRepository claims;

    public Dues(RateRepository rates, SheetRepository sheets, ClaimRepository claims) {
        this.rates = rates;
        this.sheets = sheets;
        this.claims = claims;
    }

    /**
     * How a claim's live figures round: by the sheet's policy date against the claim's date, or for a
     * correction the date of the claim it corrects (its own when that claim is not found).
     */
    private RoundingMode rounding(Claim claim, Sheet sheet) {
        LocalDate date = claim.getDate();
        if (claim.getCorrects() != null) {
            date = claims.findBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
                    .map(Claim::getDate).orElse(date);
        }
        return sheet == null ? RoundingMode.HALF_EVEN : sheet.roundingOn(date);
    }

    /**
     * The due figure a claim shows: the one fixed when it was settled, else (unless it is PENDING,
     * which is not bound) the one its person's last statement bound it to, else its amount at the rate the grade has in force on the claim's date;
     * null (n/a) when there is none.
     */
    public BigDecimal figure(Claim claim, String grade) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING ? claim.getStatedDue() : live(claim, grade);
    }

    /**
     * The due a claim shows: its figure (see {@link #figure}) with the late charge on top while it is
     * overdue; a settled claim's figure already holds the charge it was settled with. Null (n/a) when
     * it has no figure.
     */
    public BigDecimal due(Claim claim, String grade) {
        return withLate(claim, figure(claim, grade));
    }

    /**
     * The due a claim is settled at: the figure a statement bound it to, else its live figure, with
     * the late charge it has on the sheet's today on top; null when it has no figure.
     */
    public BigDecimal settling(Claim claim, String grade) {
        return withLate(claim, claim.isStated() ? claim.getStatedDue() : live(claim, grade));
    }

    /**
     * The due a PENDING claim is approved at: its live figure (a statement does not bind it while
     * PENDING) with the late charge it has on the sheet's today on top; null when it has no figure.
     */
    public BigDecimal approving(Claim claim, String grade) {
        return withLate(claim, live(claim, grade));
    }

    /**
     * The due a SETTLED claim is re-settled at: what it would show today as an OPEN claim bound by no
     * statement, its live figure with the late charge it would have on the sheet's today on top; null
     * when it has no figure.
     */
    public BigDecimal resettling(Claim claim, String grade) {
        BigDecimal figure = live(claim, grade);
        return figure == null || claim.isCorrection() ? figure : lateOn(claim, figure);
    }

    /**
     * A figure with the claim's late charge on top: the sheet's late percent of the figure for every
     * full 30 days an OPEN or PENDING claim is past its due-by (fixed when it was added) on the sheet's
     * today, rounded by the claim's date against the policy date. The charge is never bound: it always follows the sheet's today.
     * A correction has no late charge.
     */
    private BigDecimal withLate(Claim claim, BigDecimal figure) {
        if (figure == null || claim.isCorrection() || !claim.getStatus().isOpen() || claim.getSettledDue() != null) {
            return figure;
        }
        return lateOn(claim, figure);
    }

    /** A figure with the late charge an OPEN claim would have on the sheet's today on top. */
    private BigDecimal lateOn(Claim claim, BigDecimal figure) {
        Sheet sheet = sheets.findById(claim.getSheetId()).orElse(null);
        if (sheet == null || sheet.getLatePct().signum() == 0) {
            return figure;
        }
        LocalDate dueBy = claim.getDueBy();
        long periods = ChronoUnit.DAYS.between(dueBy, sheet.getToday()) / 30;
        if (periods <= 0) {
            return figure;
        }
        BigDecimal late = figure.multiply(sheet.getLatePct()).multiply(BigDecimal.valueOf(periods))
                .movePointLeft(2).setScale(2, rounding(claim, sheet));
        return figure.add(late);
    }

    /**
     * A claim's amount at the rate the grade has in force on the claim's date, raised to the sheet's
     * floor when below it (a correction has no floor), rounded by the claim's date against the policy
     * date; null when it has no rate.
     */
    public BigDecimal live(Claim claim, String grade) {
        Sheet sheet = sheets.findById(claim.getSheetId()).orElse(null);
        BigDecimal floor = claim.isCorrection() || sheet == null ? null : sheet.getFloor();
        RoundingMode rounding = rounding(claim, sheet);
        return rates.findInForce(claim.getSheetId(), grade, claim.getDate())
                .map(rate -> due(claim.getAmount(), rate, rounding))
                .map(due -> floor != null && due.compareTo(floor) < 0 ? floor : due)
                .orElse(null);
    }

    /** What is due on an amount at a rate: the amount times the percent over 100, rounded as given. */
    private static BigDecimal due(BigDecimal amount, Rate rate, RoundingMode rounding) {
        return amount.multiply(rate.getPct()).movePointLeft(2).setScale(2, rounding);
    }
}
     * The PENDING claim a steward approves or rejects; refused when it is not PENDING, when its date
     * is inside a closed period, or when the user is not a steward.
     */
    private Claim pending(String sheetId, String user, long claimId) {
        Claim claim = claim(sheetId, claimId);
        periods.refuseIfClosed(sheetId, claim.getDate());
        if (claim.getStatus() != ClaimStatus.PENDING) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim is not pending approval.");
        }
        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward approves or rejects a claim.");
        }
        return claim;
    }

    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit. */
    private boolean overClerkLimit(String sheetId, String user, BigDecimal due) {
        BigDecimal limit = sheets.clerkLimit(sheetId);
        if (limit == null || due == null || due.compareTo(limit) <= 0) {
            return false;
        }
        return Role.CLERK.equals(roles.roleOf(sheetId, user));
    }

    /**
     * Refuse a correction (an amount below 0.00) unless it names, by number, a SETTLED claim of the
     * same person; and refuse naming a claim to correct on any other claim.
     */
    private void refuseUnlessCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
        if (amount.signum() >= 0) {
            if (corrects != null) {
                throw new ResponseStatusException(HttpStatus.CONFLICT,
                        "Only a correction, with an amount below 0.00, names a claim it corrects.");
            }
            return;
        }
        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
                .filter(corrected -> corrected.getStatus() == ClaimStatus.SETTLED)
                .isPresent();
        if (!settled) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A correction must name the number of a SETTLED claim of the same person.");
        }
    }

    /** Refuse a claim dated after its person's retirement. */
    private static void refuseIfRetired(Person person, LocalDate date) {
        if (!person.canClaimOn(date)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    person.getName() + " is retired from " + person.getRetiredFrom() + ": a claim cannot be dated after it.");
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';

/** The roles a user name can have on a sheet; a name with none set is a clerk. */
export const ROLES = ['clerk', 'steward'] as const;
export type RoleName = (typeof ROLES)[number];

export interface RoleView {
  user: string;
  role: RoleName;
}

export interface SettingsView {
  /** The clerk limit with two decimals, e.g. "1.50"; null when there is no limit. */
  clerkLimit: string | null;
  /** The floor with two decimals, e.g. "1.00": a claim's live due is at least it. */
  floor: string;
  /** The terms in days: a claim is due by its date plus them. */
  terms: number;
  /** The late percent with two decimals, e.g. "10.00": an overdue claim gains it of its figure every full 30 days. */
  latePct: string;
  /** The policy date (yyyy-mm-dd); null when blank (the sheet's today is then the policy date). */
  policyDate: string | null;
  /** Period numbering from (yyyy-mm-dd): claims opened on or after it are numbered within their period; null when off. */
  periodNumberingFrom: string | null;
  /** Each grade's own terms in days; null when the grade uses the sheet's terms. */
  termsA: number | null;
  termsB: number | null;
  termsC: number | null;
  /** The cap with two decimals, e.g. "8.00": a person's due-total is at most it; null when there is none. */
  cap: string | null;
}

/** The grades that can have their own terms. */
export const GRADES = ['A', 'B', 'C'] as const;
export type Grade = (typeof GRADES)[number];

/** A grade's terms as the form takes them: a whole number of days, or blank for the sheet's terms. */
export const GRADE_TERMS = /^(\d{1,4})?$/;

/** A clerk limit as the form takes it: up to two decimals, or blank for no limit. */
export const LIMIT = /^(\d{1,12}(\.\d{1,2})?)?$/;

/** A cap as the form takes it: up to two decimals, or blank for no cap. */
export const CAP = /^(\d{1,12}(\.\d{1,2})?)?$/;

/** A floor as the form takes it: 0.00 or more, with up to two decimals. */
export const FLOOR = /^\d{1,12}(\.\d{1,2})?$/;

/** A late percent as the form takes it: 0.00 or more, with up to two decimals. */
export const LATE_PCT = /^\d{1,3}(\.\d{1,2})?$/;

/** A policy date as the form takes it: yyyy-mm-dd, or blank for the sheet's today. */
export const POLICY_DATE = /^(\d{4}-\d{2}-\d{2})?$/;

/** A period-numbering-from date as the form takes it: yyyy-mm-dd, or blank for off. */
export const PERIOD_NUMBERING_FROM = /^(\d{4}-\d{2}-\d{2})?$/;

/** Terms as the form takes them: a whole number of days. */
export const TERMS = /^\d{1,4}$/;

// The sheet's settings and the roles its user names have, read from and written to the store.
@Injectable({ providedIn: 'root' })
export class SettingsApi {
  private readonly http = inject(HttpClient);

  get(sheet: string): Promise<SettingsView> {
    return firstValueFrom(this.http.get<SettingsView>(`${this.url(sheet)}/settings`));
  }

  /** Set the clerk limit; a blank value means no limit. */
  setClerkLimit(sheet: string, value: string): Promise<SettingsView> {
    return firstValueFrom(this.http.put<SettingsView>(`${this.url(sheet)}/settings/clerk-limit`, { value }));
  }

  /** Set the cap; a blank value means no cap. */
  setCap(sheet: string, value: string): Promise<SettingsView> {
    return firstValueFrom(this.http.put<SettingsView>(`${this.url(sheet)}/settings/cap`, { value }));
  }

  /** Set the floor. */
  setFloor(sheet: string, value: string): Promise<SettingsView> {
