import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { ClaimView, LateTerms, cents, isCorrection, latePeriods, money } from './claims';
import { Grade } from './people';

export interface RateView {
  grade: Grade;
  /** The percent with two decimals, e.g. "12.50". */
  pct: string;
  /** The date (yyyy-mm-dd) the rate applies from; null when it applies from the beginning of time. */
  from: string | null;
  /** The last date (yyyy-mm-dd) the rate applies on; null when it has no end. */
  to: string | null;
}

/**
 * A rate as set through the form; a null from-date applies from the beginning of time, a null
 * to-date has no end.
 */
export interface RateForm {
  pct: string;
  from: string | null;
  to: string | null;
}

/** A from-date as a rate takes it: yyyy-mm-dd. */
export const FROM_DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * The rate a grade has in force on a date (yyyy-mm-dd): of its rates with no from-date or one on or
 * before the date, the one with the latest; null when the date is before every rate of the grade, or
 * after that one's to-date.
 */
export function rateOn(rates: RateView[], grade: Grade, date: string): string | null {
  let best: RateView | null = null;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (best === null || (r.from !== null && (best.from === null || r.from > best.from))) best = r;
  }
  if (best === null || (best.to !== null && best.to < date)) return null;
  return best.pct;
}

/** Whether two rates are for the same grade and from-date, so one replaces the other. */
export function sameSlot(a: RateView, b: RateView): boolean {
  return a.grade === b.grade && a.from === b.from;
}

/** A percent as a rate takes it: 0.00 or more, with up to two decimals. */
export const PERCENT = /^\d{1,3}(\.\d{1,2})?$/;

/** Shown in place of a due when the grade has no rate. */
export const NO_RATE = 'n/a';

/**
 * What is due on an amount in whole cents at a rate (a two-decimal percent): the amount times the
 * rate divided by 100, rounded half to even (or half up) to whole cents (a negative amount rounds as
 * its opposite does). Worked in integers so it is exact.
 */
export function dueCents(amountCents: number, pct: string, times = 1, halfUp = false): number {
  if (amountCents < 0) return -dueCents(-amountCents, pct, times, halfUp);
  const [whole, frac = ''] = pct.split('.');
  const basisPoints = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0'));
  const exact = BigInt(amountCents) * basisPoints * BigInt(times);
  const quotient = exact / 10000n;
  const remainder = exact % 10000n;
  const up = remainder > 5000n || (remainder === 5000n && (halfUp || quotient % 2n === 1n));
  return Number(up ? quotient + 1n : quotient);
}

/** What is due on an amount in whole cents at a rate, shown with two decimals; n/a with no rate in force. */
export function due(amountCents: number, pct: string | null): string {
  return pct === null ? NO_RATE : money(dueCents(amountCents, pct));
}

/**
 * A claim's due in whole cents: the due fixed when it was settled (its late charge frozen in), or
 * else its figure — the one its person's last statement bound it to (unless it is PENDING), or else its amount at the rate
 * the grade has in force on the claim's date raised to the sheet's floor (in whole cents) when below
 * it — with the late charge on top: the late percent of the figure for every full 30 days the claim
 * is overdue. Live figures round half up when `halfUp` (see roundsHalfUp), else half to even. The
 * charge is never bound by a statement. A correction has no floor and no late charge. Null when there
 * is no figure.
 */
export function claimDueCents(
  claim: ClaimView,
  rates: RateView[],
  grade: Grade,
  floorCents: number,
  late: LateTerms,
  halfUp = false,
): number | null {
  if (claim.settledDue !== null) return cents(claim.settledDue);
  let figure: number | null;
  if (claim.stated && claim.status !== 'PENDING') {
    figure = claim.statedDue === null ? null : cents(claim.statedDue);
  } else {
    const pct = rateOn(rates, grade, claim.date);
    const live = pct === null ? null : dueCents(cents(claim.amount), pct, 1, halfUp);
    figure = live === null || isCorrection(claim) ? live : Math.max(live, floorCents);
  }
  if (figure === null || isCorrection(claim)) return figure;
  return figure + dueCents(figure, late.pct, latePeriods(claim, late), halfUp);
}

// The rates for the grades on a sheet, read from and written to the store.
@Injectable({ providedIn: 'root' })
export class RatesApi {
  private readonly http = inject(HttpClient);

  /** The sheet's rates, each grade's by from-date; a grade with no rate is not listed. */
  list(sheet: string): Promise<RateView[]> {
    return firstValueFrom(this.http.get<RateView[]>(this.url(sheet)));
  }

  /** Set a grade's rate from a date, replacing any it had from that date. */
  set(sheet: string, grade: Grade, form: RateForm): Promise<RateView> {
    return firstValueFrom(this.http.put<RateView>(`${this.url(sheet)}/${grade}`, form));
  }

  private url(sheet: string): string {
    return `/api/sheets/${encodeURIComponent(sheet)}/rates`;
  }
}
  protected readonly actions: { action: ClaimAction; label: string }[] = [
    { action: 'open', label: 'Open' },
    { action: 'settle', label: 'Settle' },
    { action: 'approve', label: 'Approve' },
    { action: 'reject', label: 'Reject' },
    { action: 'void', label: 'Void' },
    { action: 'resettle', label: 'Re-settle' },
  ];
  /** The people a claim of this person can be reassigned to. */
  protected readonly others = computed(() => this.people().filter((p) => p.id !== this.personId()));
  /** The person chosen on each claim's row to reassign it to, by claim id. */
  protected readonly reassignTo = signal<Record<number, number>>({});
  /** The reason typed on each claim's row for rejecting it, by claim id. */
  protected readonly rejectReasons = signal<Record<number, string>>({});

  /**
   * What is due on a claim: the due fixed when it was settled, or else the figure its person's last
   * statement bound it to, or else its amount at the rate the
   * person's grade has in force on the claim's date (n/a when it is dated before every rate), with
   * its late charge on top while it is overdue.
   */
  protected dueOf(claim: ClaimView): string {
    const late = { pct: this.session.latePct(), today: this.session.today() ?? '' };
    const halfUp = roundsHalfUp(claim, this.claims(), this.session.policyDate(), late.today);
    const figure = claimDueCents(claim, this.rates(), gradeOn(this.grades(), claim.date), cents(this.session.floor()), late, halfUp);
    return figure === null ? NO_RATE : money(figure);
  }

  /** A claim's due-by, fixed when it was added. */
  protected dueByOf(claim: ClaimView): string {
    return dueBy(claim);
  }

  /** Whether a claim is OPEN and due by a date before the sheet's today. */
  protected overdueOf(claim: ClaimView): boolean {
    return overdue(claim, this.session.today() ?? '');
  }

  /** The name of the period a claim's date falls in; empty when it falls in none. */
  protected periodOf(claim: ClaimView): string {
    return periodOn(this.periods(), claim.date)?.name ?? '';
  }

  protected checked(event: Event): boolean {
    return (event.target as HTMLInputElement).checked;
  }

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

    const totals = this.periodDueTotals();
    return this.periods().map((p) => ({ name: p.name, dueTotal: totals.get(p.id) ?? '0.00' }));
  });
  /** Per status: how many of the sheet's claims have it. */
  protected readonly statusSummary = computed<StatusSummary[]>(() =>
    SUMMARY_STATUSES.map((status) => ({
      status,
      count: this.claims().filter((c) => c.status === status).length,
    })),
  );
  /** The sheet's floor in whole cents: a claim's live due is at least it. */
  private readonly floorCents = computed(() => cents(this.session.floor()));
  /** The sheet's cap in whole cents: a person's due-total is at most it; null when there is none. */
  private readonly capCents = computed(() => (this.session.cap() === '' ? null : cents(this.session.cap())));
  /** The sheet's today, on which each grade's rate in force is read. */
  protected readonly today = computed(() => this.session.today() ?? '');
  /** What late charges are worked from: the sheet's late percent and today. */
  private readonly late = computed(() => ({ pct: this.session.latePct(), today: this.today() }));
  protected readonly claimedTotal = computed(() =>
    money(this.people().reduce((sum, p) => sum + this.claimedCents(p.id), 0)),
  );
  /** Everyone's due-total added up, skipping those shown as n/a. */
  protected readonly dueTotal = computed(() =>
    money(
      this.people().reduce((sum, p) => sum + (this.dueTotalCents(p) ?? 0), 0),
    ),
  );
  /** How many overdue claims count in the live totals, across everyone. */
  protected readonly overdueCount = computed(() =>
    this.people().reduce((sum, p) => sum + this.overdueOf(p.id).length, 0),
  );
  /** The due of everyone's counting overdue claims added up. */
  protected readonly overdueTotal = computed(() =>
    money(this.people().reduce((sum, p) => sum + this.overdueCents(p), 0)),
  );
  protected readonly name = signal('');
  protected readonly grade = signal<Grade>('A');
  /** The date the grade entered is in force from; the sheet's today unless another is typed. */
  protected readonly gradeFrom = signal('');
  /** The id of the person open in the form, or null when the form adds a new person. */
  protected readonly editing = signal<number | null>(null);
  /** The version of the person open in the form, as it was loaded. */
  private readonly version = signal(0);
  protected readonly error = signal<string | null>(null);
  /** The refusal of the last action taken on a person's row, shown on that row. */
  protected readonly personError = signal<{ id: number; message: string } | null>(null);
  /** The person chosen in each row's patron list, by person id. */
  protected readonly patronChoices = new Map<number, string>();
  /** The refusal of the last patron added on a person's row, shown on that row. */
  protected readonly patronError = signal<{ id: number; message: string } | null>(null);
  /** A submit is waiting for its answer: a second submit meanwhile is ignored. */
  private busy = false;
  /** The ids of the claims ticked for a bulk action. */
  protected readonly selectedClaims = signal<ReadonlySet<number>>(new Set());
  /** How many claims the last bulk open opened and refused; null until one is done. */
  protected readonly bulkOpened = signal<{ opened: number; refused: number } | null>(null);
  protected readonly bulkOpenError = signal<string | null>(null);
  /** How many claims the last bulk settle settled (or sent PENDING) and refused; null until one is done. */
  protected readonly bulkSettled = signal<{ settled: number; refused: number } | null>(null);
  protected readonly bulkSettleError = signal<string | null>(null);

  constructor() {
    // Every sheet load re-reads the sheet's people from the store.
    effect(() => {
      const sheet = this.session.sheet();
      this.session.loads();
      untracked(() => {
        this.people.set([]);
        this.claims.set([]);
        this.rates.set([]);
        this.periods.set([]);
        this.reset();
        this.personError.set(null);
        this.retireDates.clear();
        this.holdDrafts.set(new Map());
        this.patronError.set(null);
        this.patronChoices.clear();
        this.selectedClaims.set(new Set());
        this.bulkOpened.set(null);
        this.bulkOpenError.set(null);
        this.bulkSettled.set(null);

  /** A person's due-total for a period (see personPeriodCents). */
  protected periodTotalOf(period: PeriodView, person: PersonView): string {
    return money(this.personPeriodCents().get(period.id)?.get(person.id) ?? 0);
  }

  /** A person's excess: by how much the sum of their figures is above the cap, else 0.00 (n/a is not capped). */
  protected excessOf(person: PersonView): string {
    const sum = this.dueSumCents(person);
    const cap = this.capCents();
    return money(sum !== null && cap !== null && sum > cap ? sum - cap : 0);
  }

  /** The sum of a person's due figures in whole cents before the cap, or null (n/a; see dueTotalCents). */
  private dueSumCents(person: PersonView): number | null {
    const dues = this.countingOf(person.id).map((c) => this.dueCents(c, person));
    if (this.pctOf(this.gradeOf(person)) === null && dues.every((d) => d === null)) return null;
    return dues.reduce<number>((sum, d) => sum + (d ?? 0), 0);
  }

  /**
   * A claim's due in whole cents at the grade its person has in force on its date, with its late charge
   * (see claimDueCents).
   */
  private dueCents(claim: ClaimView, person: PersonView): number | null {
    const halfUp = roundsHalfUp(claim, this.claimsOf(person.id), this.session.policyDate(), this.today());
    return claimDueCents(claim, this.rates(), gradeOn(person.grades, claim.date), this.floorCents(), this.late(), halfUp);
  }

  /** A person's patrons' names, sorted, comma and space separated. */
  protected patronsOf(person: PersonView): string {
    return this.patrons(person)
      .map((p) => p.name)
      .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
      .join(', ');
  }

  /** A person's backing: their patrons' due-totals added up, skipping those shown as n/a. */
  protected backingOf(person: PersonView): string {
    return money(this.patrons(person).reduce((sum, p) => sum + (this.dueTotalCents(p) ?? 0), 0));
  }

  private patrons(person: PersonView): PersonView[] {
    return this.people().filter((p) => person.patronIds.includes(p.id));
  }

  /** Name the person chosen on a person's row as their patron. */
  protected async addPatron(person: PersonView): Promise<void> {
    this.patronError.set(null);
    this.personError.set(null);
    const sheet = this.session.sheet();
    if (!sheet) return;
